SELECT r.id as r_id, r.donor_id as r_donor, r.log_id as r_log, r.agent_name as r_agent, r.receipt_no, r.donor_name, r.amount, be.id as be_id, be.status, be.agent_name as be_agent, be.donor_id as be_donor FROM receipts r LEFT JOIN bank_audit_entries be ON be.receipt_id = r.id WHERE r.donor_id IS NOT NULL AND r.log_id IS NULL AND (r.agent_name IS NULL OR r.agent_name = '' OR r.agent_name ILIKE '%suspense%') ORDER BY r.id DESC LIMIT 15;
